diff --git a/crates/panopt-core/src/model.rs b/crates/panopt-core/src/model.rs
index c0dd8ec..94b2f77 100644
--- a/crates/panopt-core/src/model.rs
+++ b/crates/panopt-core/src/model.rs
@@ -249,9 +249,10 @@ pub mod process_status {
     pub const RUNNING: &str = "running";
     /// `process_stop` signalled the process; the pane is left standing.
     pub const STOPPED: &str = "stopped";
-    /// Pane death observed (reserved for #142; not written here). Allowed to be
-    /// unused until the liveness child consumes it.
-    #[allow(dead_code)]
+    /// The instance's OS process is gone: written by the daemon's liveness
+    /// sweep ([`crate::Store::sweep_dead_processes`], todo #142/#163) when a
+    /// `running` row's pid no longer exists - the hand-quit path that
+    /// `process_stop` (which writes `STOPPED`) does not cover.
     pub const EXITED: &str = "exited";
 }

diff --git a/crates/panoptd/src/handler.rs b/crates/panoptd/src/handler.rs
index 6859863..6d6ba27 100644
--- a/crates/panoptd/src/handler.rs
+++ b/crates/panoptd/src/handler.rs
@@ -628,6 +628,23 @@ fn signal_terminate(pid: i64) {
     }
 }

+/// Whether a co-located process is still alive, the predicate the daemon feeds
+/// to [`panopt_core::Store::sweep_dead_processes`] (bug #163). `kill(pid, 0)`
+/// sends no signal - it only asks the kernel whether the pid is deliverable:
+/// `0` means alive, `EPERM` means alive-but-not-ours (still alive), `ESRCH`
+/// means gone. Treats anything but a clean "gone" as alive so the sweep never
+/// reaps a live instance on an ambiguous error. Only meaningful for instances
+/// on the daemon's own host (the documented co-located assumption).
+pub(crate) fn pid_is_alive(pid: i64) -> bool {
+    // SAFETY: `kill` with signal 0 performs only an existence/permission check;
+    // no memory effects, and a bad pid is reported via errno, which we read.
+    let rc = unsafe { libc::kill(pid as libc::pid_t, 0) };
+    if rc == 0 {
+        return true;
+    }
+    std::io::Error::last_os_error().raw_os_error() != Some(libc::ESRCH)
+}
+
 fn json_result<T: Serialize>(value: &T) -> Result<CallToolResult, McpError> {
     let json =
         serde_json::to_string(value).map_err(|e| McpError::internal_error(e.to_string(), None))?;
diff --git a/crates/panoptd/src/main.rs b/crates/panoptd/src/main.rs
index c562b37..f96d5f4 100644
--- a/crates/panoptd/src/main.rs
+++ b/crates/panoptd/src/main.rs
@@ -163,6 +163,49 @@ async fn main() -> anyhow::Result<()> {
         }
     });

+    // Reap instances whose OS process is gone, every 3s, so a hand-quit agent
+    // (Ctrl-c/exit in its pane, no `process_stop`) stops being reported as live
+    // and its row leaves `processes.md` promptly (bug #163). Faster cadence than
+    // the registry sweep: a quit should reflect in the cockpit within a tick.
+    let liveness_state = shared.clone();
+    tokio::spawn(async move {
+        let mut ticker = tokio::time::interval(std::time::Duration::from_secs(3));
+        loop {
+            ticker.tick().await;
+            let reaped = {
+                let mut st = liveness_state.lock().expect("state mutex poisoned");
+                st.sweep_dead_processes(handler::pid_is_alive)
+            };
+            match reaped {
+                Ok(dead) => {
+                    for (project, id) in dead {
+                        tracing::info!(project, process = id, "instance reaped (process gone)");
+                    }
+                }
+                Err(e) => tracing::warn!("process liveness sweep failed: {e}"),
+            }
+        }
+    });
+
+    // Re-project processes.md every 10s so time-based annotations advance even
+    // when no mutation fired - the `idle:` presence age (#142/#163) is computed
+    // at render time, so without this it freezes between mutations. Skips
+    // projects with no live agent, so an idle daemon stays quiet.
+    let projection_state = shared.clone();
+    tokio::spawn(async move {
+        let mut ticker = tokio::time::interval(std::time::Duration::from_secs(10));
+        loop {
+            ticker.tick().await;
+            let result = {
+                let st = projection_state.lock().expect("state mutex poisoned");
+                st.tick_process_projections()
+            };
+            if let Err(e) = result {
+                tracing::warn!("process projection tick failed: {e}");
+            }
+        }
+    });
+
     let token_path = default_token_path()?;
     let token = panopt_core::auth::ensure_token(&token_path)
         .with_context(|| format!("ensuring panopt token at {}", token_path.display()))?;

